package zw.ac.msu.dzimbahub.auth;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import zw.ac.msu.dzimbahub.security.JwtService; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final AppUserRepository users; private final PasswordEncoder encoder; private final JwtService jwt;
 public AuthController(AppUserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}
 public record SignupRequest(@NotBlank @Size(min=2,max=100) String fullName,@NotBlank @Email @Size(max=180) String email,@NotBlank @Size(min=8,max=72) String password, UserRole role){}
 public record LoginRequest(@NotBlank @Email String email,@NotBlank String password){}
 public record UserResponse(Long id,String fullName,String email,String role,String status){} public record AuthResponse(String token,UserResponse user){}
 private UserResponse toResponse(AppUser u){return new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getRole().name(),u.getStatus().name());}
 @PostMapping("/signup") public ResponseEntity<?> signup(@Valid @RequestBody SignupRequest body){String email=body.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))return ResponseEntity.status(409).body(Map.of("message","An account with this email already exists."));UserRole role=body.role()==null?UserRole.TENANT:body.role();if(role==UserRole.ADMIN)return ResponseEntity.badRequest().body(Map.of("message","Administrator accounts can only be created by the system owner."));AppUser user=new AppUser(body.fullName().trim(),email,encoder.encode(body.password()),role);user.setStatus(AccountStatus.PENDING);users.save(user);return ResponseEntity.status(202).body(Map.of("message","Signup request submitted. An administrator must approve your account before you can sign in.","status","PENDING"));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest body){AppUser user=users.findByEmailIgnoreCase(body.email().trim()).orElse(null);if(user==null||!encoder.matches(body.password(),user.getPasswordHash()))return ResponseEntity.status(401).body(Map.of("message","Email or password is incorrect."));if(user.getStatus()==AccountStatus.PENDING)return ResponseEntity.status(403).body(Map.of("message","Your signup request is awaiting administrator approval."));if(user.getStatus()==AccountStatus.REJECTED)return ResponseEntity.status(403).body(Map.of("message","Your signup request was not approved. Please contact the administrator."));return ResponseEntity.ok(new AuthResponse(jwt.generate(user.getEmail(),user.getRole().name()),toResponse(user)));}
 @GetMapping("/me") public UserResponse me(Authentication a){if(a==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please sign in.");return toResponse(users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account not found.")));}
}
